SELECT id, date, gross_sales, discounts, service_fee, tax, adj_amount, tender_amount,
       diners, tables_used, returning_customers, new_customers
FROM ${table}


        date BETWEEN #{start} AND #{end}


ORDER BY date DESC

SELECT id, date, day_name, c_beverage, c_kitchen, c_grab, c_foodpanda, c_shopee, c_total
FROM ${table}


        date BETWEEN #{start} AND #{end}


ORDER BY date DESC
